import pytest
import requests


class TestFeatureEndpoint:
    """Test suite for /api/data/feature endpoint"""
    
    @pytest.mark.parametrize("bbox_param,format_param,expected_status", [
        # Happy path scenarios
        (None, None, 200),
        ("40,-90,45,-85", None, 200),
        (None, "raw", 200),
        ("40,-90,45,-85", "raw", 200),
        ("40,-90,45,-85", "json", 200),
        
        # Edge cases for bbox parameter
        ("", None, 200),  # Empty bbox
        ("40,-90,45,-85,50,-80", None, 200),  # Extra coordinates
        ("40.123,-90.456,45.789,-85.123", None, 200),  # Decimal coordinates
        
        # Invalid bbox formats that should trigger 400
        ("invalid_bbox", None, 400),
        ("40,-90,45", None, 400),  # Incomplete coordinates
        ("40,-90,45,-85,extra", None, 400),  # Malformed format
    ])
    def test_feature_endpoint_parameter_combinations(self, api_client, bbox_param, format_param, expected_status):
        """Test various combinations of bbox and format parameters"""
        params = {}
        
        if bbox_param is not None:
            params['bbox'] = bbox_param
        if format_param is not None:
            params['format'] = format_param
        
        response = api_client.get('/api/data/feature', params=params)
        
        assert response.status_code == expected_status, (
            f"Expected status {expected_status}, got {response.status_code}. "
            f"Params: {params}, Response: {response.text}"
        )
        
        if expected_status == 200:
            # Successful response should have content
            assert response.content is not None
            assert len(response.content) > 0
        elif expected_status == 400:
            # Error response should have error structure
            if 'application/json' in response.headers.get('content-type', ''):
                error_data = response.json()
                assert 'error' in error_data or 'errors' in error_data

